    "Limite les transitions et les effets de l’interface.": "Limits transitions and effects in the interface.",
    "Les préférences de réduction des mouvements de ton appareil restent respectées.": "Your device’s reduce motion settings are still respected.",
    "Ton rappel d’entraînement": "Your practice reminder",
    "Quelques minutes suffisent pour progresser. Choisis le moment qui te convient.": "A few minutes are enough to make progress. Pick the time that suits you.",
    "Tu sais ce qui est enregistré et tu gardes le contrôle.": "You know what’s saved and you stay in control.",
    "Sur ton appareil": "On your device",
    "Tes cours, ta progression et tes bases importées.": "Your lessons, your progress and your imported databases.",
    "Ton prénom, ton objectif, tes leçons, tes défis, tes cartes, tes notes, ton planning et tes bases importées restent sur cet appareil.": "Your first name, your goal, your lessons, challenges, cards, notes, schedule and imported databases stay on this device.",
    "Le moteur SQL tourne dans l’appli : tes requêtes ne quittent pas ton appareil, sauf celles des parties en salle, vérifiées en ligne.": "The SQL engine runs inside the app: your queries never leave your device, except those from room games, which are checked online.",
    "En ligne": "Online",
    "Ce qu’il faut pour jouer à plusieurs et te répondre, et des statistiques si tu les acceptes.": "What’s needed to play with others and to answer you, plus statistics if you accept them.",
    "<1>Ton pseudo</1>, avec un identifiant tiré au hasard : ni ton nom, ni ton e-mail. Ton pays aussi, si tu choisis de l’afficher.": "<1>Your username</1>, with a randomly generated ID: not your name, not your email. Your country too, if you choose to show it.",
    "<1>Le classement</1> : tes points, tes parties et les défis réussis.": "<1>The leaderboard</1>: your points, your games and the challenges you solved.",
    "<1>Les salles</1> : tes temps, tes réactions et tes messages, effacés au bout de {1} heures.": "<1>Rooms</1>: your times, your reactions and your messages, deleted after {1} hours.",
    "<1>« Contacte-nous »</1> : ton message, ce que tu y joins et ton e-mail si tu le donnes, pour te répondre. Le message est effacé au bout de {1} ans.": "<1>“Contact us”</1>: your message, what you attach and your email if you give it, so we can answer you. The message is deleted after {1} years.",
    "<1>Tes avis</1> sur les leçons et ton vote pour le prochain parcours, sans ton prénom.": "<1>Your ratings</1> of lessons and your vote for the next path, without your first name.",
    "<1>Des statistiques d’usage anonymes</1>, si tu les acceptes : écrans de l’accueil vus, jours d’usage, flammes, leçons, défis, parties, paywall vu. Sans lien avec toi ni ton pseudo. Gardées {1} mois.": "<1>Anonymous usage statistics</1>, if you accept them: home screens viewed, days of use, flames, lessons, challenges, games, paywall views. Not linked to you or your username. Kept {1} months.",
    "Tout est hébergé chez Supabase, à Paris.": "Everything is hosted by Supabase, in Paris.",
    "Ta confidentialité": "Your privacy",
    "Personne ne voit tes requêtes.": "No one sees your queries.",
    "Dans une salle, les autres joueurs voient ton pseudo, ton drapeau, tes temps et tes réactions. Jamais tes requêtes.": "In a room, other players see your username, your flag, your times and your reactions. Never your queries.",
    "En salle, ta requête part en ligne pour être vérifiée. Seule son empreinte, un code qui ne permet pas de la relire, est gardée {1} heures au plus.": "In a room, your query goes online to be checked. Only its fingerprint, a code that can’t be read back, is kept for {1} hours at most.",
    "Ni publicité, ni traceur, rien de revendu. Si tu l’acceptes, l’appli compte comment elle est utilisée, sans savoir qui tu es. Tu choisis plus bas, et tu peux changer d’avis.": "No ads, no trackers, nothing sold. If you accept, the app counts how it’s used, without knowing who you are. You choose below, and you can change your mind.",
    "Gérer mes données": "Manage my data",
    "Télécharger une copie de tes données ou effacer tes informations.": "Download a copy of your data or delete your information.",
    "Une copie de ta progression, de tes notes et de ton planning": "A copy of your progress, your notes and your schedule",
    "Effacer la progression": "Reset progress",
    "Leçons, défis, notes et planning": "Lessons, challenges, notes and schedule",
    "<1>Effacer la progression</1> : tes leçons, défis, cartes, notes et planning sont vidés sur cet appareil, et tes scores quittent le classement. Ton pseudo reste à toi.": "<1>Reset progress</1>: your lessons, challenges, cards, notes and schedule are cleared on this device, and your scores leave the leaderboard. Your username stays yours.",
    "<1>Supprimer mon compte</1> (en bas de Mon compte ; sans compte, <2>Supprimer mes données</2>) : efface tout ce que le serveur garde pour toi et tout ce qui est sur cet appareil.": "<1>Delete my account</1> (at the bottom of My account; without an account, <2>Delete my data</2>): deletes everything the server keeps for you and everything on this device.",
    "Supprimer l’appli efface aussi ce qui est sur cet appareil. Avec un compte connecté, ta progression reste sur ton compte.": "Deleting the app also deletes what’s on this device. With a signed-in account, your progress stays on your account.",
