    /* L’onboarding ajouté le 14 novembre (statistiques, widgets, témoignages) et ses étiquettes */
    "Tu nous aides à <1>améliorer</1> Requête ?": "Will you help us <1>improve</1> Requête?",
    "Avec ton accord, nous analysons ce qui fonctionne et ce qui peut être amélioré pour rendre ton expérience encore meilleure.": "With your consent, we look at what works and what could be better, to make your experience even better.",
    "<1>Tes données restent anonymes</1>Ni ton nom, ni ton e-mail, ni ton pseudo.": "<1>Your data stays anonymous</1>Not your name, not your email, not your username.",
    "<1>Tes réponses restent privées</1>Ni tes requêtes SQL, ni ce que tu écris.": "<1>Your answers stay private</1>Not your SQL queries, not what you write.",
    "<1>Tu gardes le contrôle</1>Tu peux changer d’avis à tout moment dans Mon compte.": "<1>You stay in control</1>You can change your mind at any time in My account.",
    "Ta réponse": "Your answer",
    "Oui, avec plaisir": "Yes, happy to",
    "Non merci": "No thanks",
    "Avec un compte, ta progression te suit sur tous tes appareils.": "With an account, your progress follows you on all your devices.",
    "De vrais avis, recueillis sur le site requeteapp.com, lus par une voix de synthèse": "Real reviews, collected on requeteapp.com, read by a synthetic voice",
    "Avis de Sofia B., Data Analyst junior, {m1} {1} : « J’ai décroché mon premier poste dans la data 🥹 ! Requête m’a énormément aidée à apprendre SQL mais surtout à pratiquer. J’ai beaucoup utilisé les entraînements aux entretiens avant mes candidatures et certaines questions étaient très proches de ce qu’on m’a demandé en entretien. Aujourd’hui je suis Data Analyst, donc forcément je recommande ! » Un vrai avis, recueilli sur le site requeteapp.com.": "Review from Sofia B., Junior Data Analyst, {m1} {1}, translated from French: “I landed my first job in data 🥹! Requête helped me so much to learn SQL, and above all to practice. I used the interview practice a lot before applying, and some questions were very close to what I was asked in my interviews. Today I’m a Data Analyst, so of course I recommend it!” A real review, collected on requeteapp.com.",
    "Je t’encouragerai directement depuis ton écran d’accueil !": "I’ll cheer you on right from your Home Screen!",
    "Requête sur ton<1/><2>écran d’accueil</2>": "Requête on your<1/><2>Home Screen</2>",
