    "Appuie ensuite sur « + », en haut à gauche, puis sur « Ajouter un widget ».": "Then tap “+” in the top-left corner, then “Add Widget”.",
    "Cherche « Requête » et ajoute mon widget !": "Search for “Requête” and add my widget!",
