    "Confidentialité": "Privacy",
    "Avec un compte : leçons, défis, notes, planning, ton pseudo, tes points et tes parties sont sauvegardés et te suivent sur tes autres appareils. Les bases que tu importes restent sur cet iPhone.": "With an account: lessons, challenges, notes, schedule, your username, your points and your games are saved and follow you on your other devices. The databases you import stay on this iPhone.",
    "En dehors de ce mode, aucune donnée n’est envoyée tant qu’aucun service de connexion n’est configuré.": "Outside this mode, no data is sent as long as no sign-in service is set up.",
    "Le rappel quotidien n’envoie une notification que si tu l’actives et autorises les notifications, à l’heure choisie.": "The daily reminder only sends a notification if you turn it on and allow notifications, at the time you choose.",
    "Requête est une app d’apprentissage SQL. Ta progression est enregistrée sur cet iPhone ; si tu te connectes avec Apple ou Google (c’est facultatif), elle est aussi sauvegardée avec ton compte.": "Requête is a SQL learning app. Your progress is saved on this iPhone; if you sign in with Apple or Google (optional), it’s also saved with your account.",
    "« Supprimer mon compte », dans Mon compte, efface d’un coup ce que le serveur garde pour cet appareil, puis tout ce qui est sur l’appareil. Le détail complet est dans la politique de confidentialité, sur requeteapp.com.": "“Delete my account”, in My account, erases at once what the server keeps for this device, then everything on the device. The full details are in the privacy policy, on requeteapp.com.",
    "L’accès aux leçons, aux défis et aux outils de pratique demande un abonnement Requête Premium, vendu par l’App Store.": "Access to the lessons, challenges and practice tools requires a Requête Premium subscription, sold through the App Store.",
    "Requête t’aide à apprendre le SQL en pratiquant. Le contenu est fourni tel quel, à des fins pédagogiques.": "Requête helps you learn SQL by practicing. The content is provided as is, for educational purposes.",
    "Tu te connectes avec Apple ou Google. Tu peux télécharger une copie de tes données, effacer ta progression ou supprimer ton compte à tout moment depuis Mon compte. Un effacement est définitif.": "You sign in with Apple or Google. You can download a copy of your data, erase your progress or delete your account at any time from My account. An erasure is permanent.",
