    /* 15 novembre, 17 h 45 : les erreurs SQL et ce que dit l’encart d’un essai raté, en anglais (errBox, errAide, defiPiege) */
    "Erreur SQL": "SQL error",
    "<1/> est propre à PostgreSQL : la base de l’app ne le connaît pas. Pour garder une seule ligne par groupe, numérote les lignes dans une sous-requête avec <2/>, puis garde le numéro {1}.": "<1/> is specific to PostgreSQL: the app’s database doesn’t know it. To keep a single row per group, number the rows in a subquery with <2/>, then keep number {1}.",
    "Vérifie l'orthographe exacte de la colonne — ou si tu voulais du texte, entoure-le de guillemets simples : <1/>.": "Check the exact spelling of the column, or if you meant text, put it in single quotes: <1/>.",
