    "renvoie la première valeur qui n’est pas vide (<1/>).": "returns the first value that isn’t empty (<1/>).",
    "requêtes": "queries",
    "retire d’abord des lignes ; <1/> retire ensuite des groupes.": "removes rows first; <1/> then removes groups.",
    "retire les lignes en double du résultat.": "removes duplicate rows from the result.",
    "retire un droit quand il n’est plus utile.": "removes a permission when it’s no longer needed.",
    "revient au même que <1/>.": "is the same as <1/>.",
    "répartit les lignes triées en {1} groupes de taille presque égale.": "splits the sorted rows into {1} groups of nearly equal size.",
    "réunit les valeurs d’un groupe dans une seule case, séparées par une virgule.": "gathers a group’s values into a single cell, separated by a comma.",
    "sans <1/> vide la table, mais la garde.": "without <1/> empties the table, but keeps it.",
    "saute les {1} premières lignes : c’est ce qui permet d’afficher la page suivante.": "skips the first {1} rows: that’s how you show the next page.",
    "se place après <1/> et garde seulement certaines lignes.": "goes after <1/> and keeps only some rows.",
    "se pose sur la clé étrangère (la colonne qui pointe vers une autre table) et décide du sort des lignes liées.": "is set on the foreign key (the column that points to another table) and decides what happens to linked rows.",
    "seul, sans <1/>, annule toute la transaction.": "on its own, without <1/>, undoes the whole transaction.",
    "suffit dans la sous-requête : seule la présence d’une ligne compte.": "is enough in the subquery: only the presence of a row matters.",
