    "Une fonction de fenêtre (<code>LAG</code>, <code>LEAD</code>, <code>RANK</code>…) ne peut pas être placée directement dans une fonction d’agrégation comme <code>AVG()</code>. Calcule-la d’abord dans un <code>WITH</code>, puis fais la moyenne sur ce résultat.": "A window function (<code>LAG</code>, <code>LEAD</code>, <code>RANK</code>…) can’t be placed directly inside an aggregate function like <code>AVG()</code>. Calculate it first in a <code>WITH</code>, then average that result.",
