    "garde au plus {1} lignes : le résultat n’en compte que {2}, elles restent donc toutes. Sans <1/>, leur ordre n’est pas garanti.": "keeps at most {1} rows: the result only has {2}, so they all stay. Without <1/>, their order isn’t guaranteed.",
